#include "watchdog_core.h"
#include "osal_atomic.h"

static int32_t Hi3516WdtGetStatus(struct WatchdogCntlr *cntlr, int32_t *status)
{
    struct Hi3516WatchdogData *priv = NULL;
    if (cntlr == NULL || status == NULL) {
        return HDF_ERR_INVALID_PARAM;
    }
    priv = (struct Hi3516WatchdogData *)cntlr->priv;
    *status = (priv->started) ? WATCHDOG_START : WATCHDOG_STOP;
    return HDF_SUCCESS;
}
